import{_ as r,a as o,b as a}from"./chunks/f0929a2bf23cb619ed62.B9l9wUoF.js";import{_ as s,C as l,o as n,c as i,j as e,a as c,E as u,a6 as h}from"./chunks/framework.CnPv4DE1.js";const T=JSON.parse('{"title":"你不成功是因为你太在乎了（如何停止在意）","description":"","frontmatter":{"title":"你不成功是因为你太在乎了（如何停止在意）","originalTitle":"You Aren’t Successful Because You Care Too Much (How To Stop Caring)","date":"2023-07-29","originalUrl":"https://thedankoe.com/letters/you-arent-successful-because-you-care-too-much-how-to-stop-caring/","minutes":12,"sourceHash":"1dd23fda19f32e2be4a764561e762173a0e496e2cc1d7e5f815b448b5805c22e","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/you-arent-successful-because-you-care-too-much-how-to-stop-caring/"}]]},"headers":[],"relativePath":"letters/you-arent-successful-because-you-care-too-much-how-to-stop-caring.md","filePath":"letters/you-arent-successful-because-you-care-too-much-how-to-stop-caring.md"}'),m={name:"letters/you-arent-successful-because-you-care-too-much-how-to-stop-caring.md"};function g(f,p,d,b,_,k){const t=l("ArticleMeta");return n(),i("div",null,[p[0]||(p[0]=e("h1",{id:"你不成功是因为你太在乎了-如何停止在意",tabindex:"-1"},[c("你不成功是因为你太在乎了（如何停止在意） "),e("a",{class:"header-anchor",href:"#你不成功是因为你太在乎了-如何停止在意","aria-label":'Permalink to "你不成功是因为你太在乎了（如何停止在意）"'},"​")],-1)),u(t),p[1]||(p[1]=h('<p><a href="https://www.youtube.com/embed/U1tVnANCDH0?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>当你相信自己能掌控未来时，你就不再在乎别人的看法了。</p><p>这句话……值得好好拆解一下。</p><p>缺乏自信是阻碍大多数人发挥潜能的罪魁祸首。他们太在乎别人的看法了。</p><p>假设你想创业，各种想法就会涌入脑海：</p><p>我父母会怎么想？</p><p>我朋友会怎么想？</p><p>我配偶会怎么想？</p><p>这能赚够钱替代我现在的收入吗？</p><p>这需要多长时间？</p><p>更别提当你真正开始创业时脑子里冒出的那些想法了。</p><p>人们之所以失败，是因为他们承受不起实现既定目标所需的情绪重量。</p><p>每产生一个追求更好生活的念头，就有100个念头把你打回原形。</p><p>而这还仅仅是关于商业的想法。</p><p>那我们每天产生的其他 6 万到 8 万个念头呢？</p><p>我们要应付的事情实在太多了。</p><p>我主动去交新朋友会不会显得很奇怪？</p><p>如果我不控制好我的债务，我的人生最终会落得什么下场？</p><p>我今天早上喂狗了吗？想象一下，如果别人知道了，会觉得我是一个多么糟糕的宠物主人。</p><p>培养自信绝非易事。</p><p>更多的信息、更多的责任以及对未来更多的选择，会让自信转化为成功，也会让焦虑转化为失败。</p><p>这就是我们所生活的现代环境。</p><p>我们该如何开始培养那种能带来自信的对自己的信任呢？</p><h2 id="自信的-4-大支柱" tabindex="-1">自信的 4 大支柱 <a class="header-anchor" href="#自信的-4-大支柱" aria-label="Permalink to &quot;自信的 4 大支柱&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>当大多数人想知道如何变得更自信时，他们会想起那条过于简单的建议：</p><p>“自信 = 能力。”</p><p>这话没错，但大多数人会把能力视为在某项特定技能上变得更精通。</p><p>于是他们就不停地学啊学啊学，从不行动，从不反思，也从未真正把自信当作一项可以在任何情况下适用的技能来培养。这是最常见的结果。</p><p>这句简单的话背后有着很少有人能看透的深度。</p><p>我们必须努力理解这句话，因为很明显，“自信=能力”作为一般性建议不仅没有解决这个世界上最大的问题之一，反而使其恶化了。</p><p><strong>支柱 1) 视角</strong></p><p>当你进入一个让你感到不自信的情境时，你的焦虑感会飙升。</p><p>这会让你的大脑除了自己的念头之外，对外界的一切关闭。</p><p>它们会疯狂滋生。</p><p>你会完全从当下情境中退缩，成为你过去的奴隶。被你曾经的经历所束缚。你还是原来的那个你。</p><p>你必须从中挣脱出来，有意识地努力重新编程你对情境的习惯性反应方式。</p><p>要做到这一点：</p><ul><li>当你进入一个情境并引发焦虑时，暂停一下</li><li>抽离出来，看清这个情境的本质，它只是一个正常的情境</li><li>把意识转移到与你处于同一情境中的其他人身上</li></ul><p>“转移意识”就是采用另一个人的视角。</p><p>大多数人都只是和我们经历着同样生活的人而已。</p><p>亿万富翁也是有同样烦恼的人。</p><p>健身模特也是有同样烦恼的人。</p><p>任何被你在心理上置于高位的人，都有着同样的烦恼。</p><p>唯一会让他们对你产生负面反应的事情，就是你把他们当成异类（不把他们当普通人看待）。</p><p>不要把他们捧得比你高。</p><p>记住，这是你正在养成的一个习惯。</p><p>它需要重复和练习。</p><p>如果你不能获得看待情境的宏观视角，你就无法推进到其他支柱。</p><p><strong>支柱 2) 感知</strong></p><p>你如何感知情境决定了你如何行动。</p><p>这要求你在进入情境之前进入一种开放的心态，并在情境中保持这种心态。</p><p>如果你在刷社交媒体时，没有把一个企业主的推文感知为主动联系的机会，你就不会去联系。</p><p>如果你确实把它看作一个机会，你仍然可能会搞砸这条信息，或者根本不发，因为你对那个人产生了错误的感知。</p><p>结交新朋友或参与艰难的对话也是如此。</p><p>感知是双向的。</p><p>你根据别人展现自己的方式，以特定的方式去感知他们。</p><p>他们也根据你展现自己的方式来感知你。</p><p>如果你看起来“不像那么回事”，或者你的举止不能引导对方产生积极的解读，事情就不会顺利。而且你潜意识里会知道这一点。你不会去参与这些情境，因为你的外表和行为方式已经让自己注定会失败。</p><p>我是一个彻头彻尾的内向者，但人们经常告诉我，从我穿衣、走路和说话的方式来看，我显得很自信。</p><p>练习吧。</p><p><strong>支柱 3) 练习</strong></p><p>你在某件事上越擅长，就能让你更好地感知情境。</p><p>把获取技能想象成一种在人生这场游戏中提升等级的方式。</p><p>在电子游戏里有“技能树”。</p><p>在你玩游戏时，你会选择相应的技能来帮助你按照自己想要的方式游玩。</p><p>随着你练习这些技能，你的经验值会增加，然后就能解锁新的技能。</p><p>这里的关键点是：</p><p><em>在练习你当前可用的技能之前，你无法获得其他的技能。</em></p><p>你之所以没有察觉到盈利机会的意识，是因为你缺乏识别、选择并对其采取行动的技能。</p><p>当你朝着目标前进时，你需要学习并练习相应的技能来实现这些目标。</p><p>如果你目标定得太高，你就会感到不知所措，不知道该学些什么。</p><p>你必须在符合你当前等级的水平上游玩，并获取达到下一个等级所需的技能。</p><p>随着你等级的提升，你的工具带里会装满各种技能，这让你能够看清你所处的层面，这个层面比你之前所在的较低层面要广阔得多。</p><p>我第一次成功的尝试是做自由职业网页设计。</p><p>这是一个任何人都能学到的单一技能。竞争激烈，还要为了更高的价格而战。</p><p>我知道，如果我想做更赚钱的事，比如为服务型企业搭建营销漏斗，我就必须学习营销、文案写作和买家旅程等技能才能做好。</p><p>然后，当我追求成为一名创作者的水平时，我需要结合我所知道的知识，并增加内容写作等新技能（我在<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>中教授你所需的所有技能）。</p><p>我的水平提升得越高，遇到的人就越多，我在多个领域的自信心也就越强。</p><p>你能做的最糟糕的事情，就是停止学习新技能，满足于你现有的水平。</p><p><strong>支柱 4) 真实</strong></p><p>真实就是做你想做的事，而不受外界想法、意见和你觉得必须顺从的信念的干扰。</p><p>当我爆粗口时，评论区有人告诉我这样很不专业，我是应该顺从他们那些相对的信念（那并非绝对的真理），还是自己独立思考？</p><p>我不在乎什么专不专业。我也不在乎被那些每个人都有不同解读的词语所冒犯。</p><p>通过真实建立自信是一场心理游戏。</p><p>你必须每天都在玩这个游戏。</p><p>你必须暂停，获取视角，感知情境，并练习情境所需的技能。</p><p>真实是你落实这自信 4 大支柱的方式。</p><h2 id="通往自信的非传统之路" tabindex="-1">通往自信的非传统之路 <a class="header-anchor" href="#通往自信的非传统之路" aria-label="Permalink to &quot;通往自信的非传统之路&quot;">​</a></h2><p><img src="'+o+'" alt=""></p><p>创业是你的天性。</p><p>去追求新的挑战，永不妥协，通过获取技能来拓展你的视角，并以金钱的形式获得你是否真正在为社会做贡献的反馈。</p><p>创业就是创造。</p><p>而作为一名创作者，就是通过你身而为人的锋芒来传导神性。</p><p>你绝对不想陷入一个挑战不再存在的境地。</p><p>就像被关在格子间里的猴子一样，你的精神会受到折磨，即使你是收入前1%的顶尖人群，你也会纳闷为什么自己的人生毫无成就感。</p><p>个人成长是通向商业增长的“入门毒药”。</p><p>而商业增长则是通往自信的非传统之路。</p><p>我在 <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a> 中将两者结合起来，这样你就可以提升自我，将自己产品化，并靠做自己来赚钱。这是一个自然的过程。</p><p><strong>1) 它要求你要么进化，要么灭亡。</strong></p><p>大多数人死于25岁。</p><p>他们找到了工作。</p><p>他们找到了配偶。</p><p>他们买了房子。</p><p>他们买了车。</p><p>他们得到了社会期望他们得到的一切。一个安逸、温顺、对社会赖以生存的系统毫无威胁的人。</p><p>生命是不断流动、不断进化的，如果你为了安于次等的生活而选择阻碍这种流动，你就算死了。</p><p>死亡是象征性的。而所有的理解都是隐喻性的。</p><p>如果生命就是成长，而成长需要新事物，那么死亡就意味着新想法、新潜能、新项目和新实践的死亡。</p><p>如果你想在这个永不停息地变化的世界中生存下来，创业能确保你不会“死”。当然，前提是你坚持到底直到成功。</p><p><strong>2) 它要求你成为你所在行业的专家。</strong></p><p>如果你的理解不到位，你就会得到不尽人意的结果。</p><p>理解不同于知识。</p><p>理解是扩张意识的向上运动。</p><p>冥想是扩张意识的向下运动。</p><p>大多数神秘主义者和心灵导师忘记了这种平衡。</p><p>这不是非要创造力<em>或</em>生产力。</p><p>也不在于做僧侣<em>还是</em>战士。</p><p>也不在于和平<em>还是</em>进步。</p><p>也不在于存在<em>还是</em>行动。</p><p>而是两者的结合。</p><p>这就是生活。</p><p>二元对立坍缩为一。</p><p>如果你只堆砌理论而不去实践，你在这个生意中就会失败。</p><p>你既需要每天学习，也需要每天执行。而不是二选一。</p><p><strong>3) 它要求你为自己和你的客户取得成果。</strong></p><p>如果你没有取得成果，你就是没有价值的。</p><p>就这么简单。</p><p>如果你没能取得成果，这并不是让你放弃的信号。这是让你去提升的信号。真正的价值需要随着时间的推移而发展。</p><p>创业是你确保在现实中将自己发展成有价值的资产的途径。</p><p><strong>4) 它要求你在刚开始做的时候做得很烂，这样你才能进步。</strong></p><p>幻想自己在一开始几乎做任何事都不会做得很烂是愚蠢的。</p><p>正是这一点阻碍了大多数人为梦想付诸行动。</p><p>一旦你跨过了第一个难关，你就会像滚雪球一样进入一个纯粹进步的阶段。</p><p><strong>5) 它要求你改变工作、休息和娱乐的习惯。</strong></p><p>你不能用让你升到2级的角色配置去打通3级。</p><p>成长需要改变，这就是为什么大多数人很早就妥协了。</p><p><strong>6) 它要求你具备心理学的技能，从而了解自己的心智。</strong></p><p>营销、销售、写作和演讲是商业成功的支柱。</p><p>在当今世界，财富是通过代码和内容产生的。</p><p>代码是互联网的后端。</p><p>内容是前端。</p><p>将两者结合起来，你便拥有了人和产品。</p><p>把人引导向产品，你便获得了利润。</p><p>你可以学习写代码，这极具价值，但除非那是你的热情所在，否则你最好去学习做内容。</p><p>你可以利用程序员构建的工具（比如网站建设器、社交媒体平台以及互联网上的其他一切）来分发你的内容。</p><p>内容需要自我了解。</p><p>你必须抓住注意力，留住注意力，并为这些注意力提供价值。</p><p>我在<a href="/letters/the-1-million-dollar-skill-stack-learn-in-this-order">《价值百万美元的技能栈》</a>中讨论过这一点。</p><h2 id="自我提升者的潜在进阶路径" tabindex="-1">自我提升者的潜在进阶路径 <a class="header-anchor" href="#自我提升者的潜在进阶路径" aria-label="Permalink to &quot;自我提升者的潜在进阶路径&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>当你试图变得更加自信时，焦虑陷阱是非常危险的。</p><p>接近陌生人时你会感到焦虑。</p><p>对建立企业所需的改变你会感到焦虑。</p><p>当你有这种感觉时，停下来。</p><p>（不，说真的，这需要你有意识地去努力……<em>停下来。</em>）</p><p>跳出局限，拉远视角。</p><p>转换你的思维。</p><p>治疗焦虑的良药是好奇心。</p><p>就是这样。这就是思维的转换。</p><p>当你对创业感到焦虑时，是因为你把目光投向了遥远的未来，以至于根本无法看清局势。你的大脑无法为你精神上所处的混乱局面带来秩序。</p><p>把你的注意力带回到你现在能做的事情上。</p><p>对你可以开始学习的东西产生好奇，然后去学。</p><p>当你处于社交场合时，停止想象你与那个人在未来的每一个小细节。</p><p>把你的注意力集中在他们身上，就在你面前的他们。</p><p>有什么东西吸引了你的眼球吗？</p><p>去问问他们。</p><p>以下是你如何利用好奇心作为杠杆来积累势能，从而打造出一门赚钱的生意（同时将自信作为副产品）。</p><p><strong>1) 从写作开始</strong></p><p>当你不自信的时候，写作是你最好的选择。</p><p>而且，它是任何以及所有内容的基础。</p><p>推文、广告、长视频、短视频等等，全都是从写实际的帖子或脚本开始的。</p><p>当其他人都在比拼外貌时，写作能让你展现你的智慧。</p><p>你不需要展示你的身材，甚至不需要露脸。（<a href="https://twitter.com/orangebook_" target="_blank" rel="noreferrer">Orange Book</a> 是我最喜欢的匿名作者之一。）</p><p>要成为一名优秀的写作者，你需要了解心理学，以此来构建能够捕捉、留住并传播注意力的信息。</p><p>要了解心理学，去学习营销和销售。这就是你学习如何在现实世界中应用心理学认知的方法。</p><p>如果要我给你指一条路，以下是开始写作的方法：</p><ul><li>选择一个你有兴趣将其作为全职工作的主题</li><li>每天抽出30分钟学习营销、销售或你感兴趣的内容</li><li>一天都不要停止学习。看视频、听播客、读书以及浏览互联网内容。</li><li>把让你印象深刻的想法记下来。</li><li>在 Twitter (X) 或 Threads 上起步，开始发布你的想法。</li><li>把社交媒体作为一项技能去学习，这样你才能成长（我在<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">《两小时写作者》（2 Hour Writer）</a>中教授了所有这些内容）。</li></ul><p>在3到6个月的时间里，你应该能获得相当数量的粉丝。</p><p>足以让你有信心把这变成你的全职生意。</p><p>一旦你有了足够的读者，你就可以创造一个产品或服务，通过你的写作来变现。</p><p>营销和销售知识在这一刻将产生复利。</p><p><strong>2) 拓展到口头表达</strong></p><p>大多数人不知道这一点，但我拓展的第一个平台不是 Instagram。而是播客。</p><p>为什么？</p><ul><li>它帮我结识了高层次的人，并获得了更多机会。</li><li>你不需要视频剪辑技能。这是从写作轻松进阶的一步。</li><li>它迫使你发现自己在与他人沟通时的盲区。</li></ul><p>我做播客不是为了变现或出名。</p><p>在播客领域，这种情况极其罕见。</p><p>我用它来约我想交谈的人通话。</p><p>人们<strong>非常喜欢</strong>上播客。</p><p>我想和 Justin Welsh 交流，所以我邀请他来做一期播客，这为我的品牌赋予了新的愿景。</p><p>我们关于一人企业的聊天成为了一个催化剂，让我在不到6周的时间里就在 YouTube 上涨了 15 万名订阅者。</p><p>那是又一个下一步。</p><p>你可以带着你之前的写作内容直接进军 YouTube。</p><p>你可以真真切切地看到，在制作了6个月的视频后，你所获得的自信心增长。</p><p>你变得不再那么尴尬，表达更加简练，且更具影响力。</p><p>你的生意随着你的自信心一起产生复利。</p><p><strong>3) 创造一个产品或服务</strong></p><p>到目前为止，你的受众正在不断增长。</p><p>你有了受众群。</p><p>好吧，希望如此。如果还没有，你需要拉远视角，意识到这是一个技能问题。你需要对社交媒体有全局的理解，以便想方设法让好内容获得曝光。</p><p>赚钱需要人和产品。</p><p>这里的“产品”也可以包括服务。它是你卖给被你吸引来的人的东西。</p><p>这是赚钱的唯一途径。</p><p>你可以立志成为极少数仅靠（社交媒体平台产生的）广告收入就能生存的人之一，但你会成为算法的奴隶。</p><p>创造你自己的产品或服务，才是你掌控收入的方式。</p><p>将社交媒体作为一项技能，它就会变成一个水龙头，你想赚更多钱时，随时可以拧开它。</p><p>你知道如何吸引人，而且你有一个卖得出去的产品。</p><p>（这两方面都大有学问，你需要在这两点上不断精进。）</p><p>我曾就此写过大量的文章，以下是一些教你如何创造产品的信件：</p><p>– <a href="/letters/the-one-person-business-revisited-turn-yourself-into-a-business">一人企业商业模式概述</a></p><p>– <a href="/letters/the-best-online-business-model-to-make-1-million-in-2023">即使作为新手，也能打造完美提案（Offer）的最佳方式</a></p><p>– <a href="/letters/you-have-100000-of-knowledge-trapped-in-your-brain">如何将你脑海中价值 10 万美元的知识产品化</a></p><p>打造产品或服务有助于建立自信，原因如下：</p><ul><li>一开始你会做得很烂。你做任何其他事情几乎也是如此。不要仅仅因为商业对你来说显得陌生就觉得它很可怕。</li><li>你能在什么需要改进方面获得直接反馈。人们可能会很苛刻，但大多数人还是很友善的。</li><li>如果你想真的赚到钱，你就得真的提供价值。如果你没有继续增长受众或财富——也许得开始思考一下你到底有多大价值了。</li></ul><p>这期就到这里了，朋友们。</p><p>去把自信当作一项技能去练习，受用终身。</p><p>– Dan Koe</p><hr><p><a href="/en/letters/you-arent-successful-because-you-care-too-much-how-to-stop-caring">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',220))])}const A=s(m,[["render",g]]);export{T as __pageData,A as default};
